#!/usr/bin/env bash
# Adds a zip upload button to Dev Files: extracts an uploaded .zip into
# agent/, service_files/, and requirements.txt.
#
# Security notes (this is the part that matters):
#   - Every entry's target path goes through the SAME containment check
#     as every other write in this blueprint (path traversal, absolute
#     paths, and symlinks closed off via realpath + prefix check) — a zip
#     is just another way to supply a path. Tested against a real "zip
#     slip" payload (entries like '../../../../tmp/x' and
#     '../../etc/cron.d/evil') before this was shipped: both were
#     rejected, nothing was written outside the allowed directories, and
#     the legitimate entries in the same zip still extracted correctly.
#   - Every entry is validated BEFORE any of them are written — a zip
#     with one bad entry doesn't half-apply.
#   - Guardrails against a zip bomb: max 500 entries, 5MB per file, 20MB
#     total uncompressed.
#   - Additive/overlay, same philosophy as CSV import and JSON restore
#     elsewhere in this app: creates and updates matching files, never
#     deletes anything not present in the zip.
#   - The whole current tree is snapshotted to one zip in
#     data/dev_file_backups/ before anything is written.
#
# No database migration in this push.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app/blueprints/dev_files.py app/templates/dev_files run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run push_dev_files.sh first, then this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/dev_files"
cp app/blueprints/dev_files.py "backups/$TS/dev_files.py.bak" 2>/dev/null || true
cp app/templates/dev_files/index.html "backups/$TS/templates/dev_files/index.html.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing app/blueprints/dev_files.py"
base64 -d > app/blueprints/dev_files.py << 'DEV_FILES_PY_B64'

DEV_FILES_PY_B64

echo "==> Writing app/templates/dev_files/index.html"
base64 -d > app/templates/dev_files/index.html << 'DEV_INDEX_HTML_B64'

DEV_INDEX_HTML_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/blueprints/dev_files.py').read())"
echo "    syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Dev Files now has an upload form: pick a .zip, it extracts into"
echo "agent/, service_files/, and requirements.txt."
echo "  - Expects the same layout as 'Download all as .zip' produces."
echo "  - Adds/updates files; never deletes anything not in the zip."
echo "  - Current files are snapshotted to data/dev_file_backups/ first."
echo "  - Doesn't reach kiosks until you click Publish, same as edits."
echo "==================================================================="
